begin;
select plan(31);

-- Synthetic, deterministic fixtures only. The final ROLLBACK removes all data.
insert into auth.users(instance_id,id,aud,role,email,raw_app_meta_data,raw_user_meta_data,created_at,updated_at)
values
 ('8b100000-0000-4000-8000-000000000001','8b100000-0000-4000-8000-000000000001','authenticated','authenticated','question-api-admin@example.invalid','{}','{}',now(),now()),
 ('8b100000-0000-4000-8000-000000000002','8b100000-0000-4000-8000-000000000002','authenticated','authenticated','question-api-user@example.invalid','{}','{}',now(),now());
insert into public.internal_admin_memberships(user_id,active) values ('8b100000-0000-4000-8000-000000000001',true);
insert into public.organizations(id,name,slug) values
 ('8b200000-0000-4000-8000-000000000001','Question API Org','question-api-org'),
 ('8b200000-0000-4000-8000-000000000002','Other Question API Org','other-question-api-org');
insert into public.training_courses(id,organization_id,course_key,status,created_by)
values ('8b300000-0000-4000-8000-000000000001','8b200000-0000-4000-8000-000000000001','question-api-course','active','8b100000-0000-4000-8000-000000000001');
insert into public.training_course_versions(id,organization_id,course_id,version_number,status,default_locale,supported_locales,title_i18n,description_i18n,created_by)
values ('8b400000-0000-4000-8000-000000000001','8b200000-0000-4000-8000-000000000001','8b300000-0000-4000-8000-000000000001',1,'draft','en',array['en','ar'],'{"en":"Question API","ar":"واجهة الأسئلة"}','{"en":"Draft","ar":"مسودة"}','8b100000-0000-4000-8000-000000000001');
insert into public.training_modules(id,organization_id,course_version_id,stable_key,position,title_i18n,description_i18n,metadata)
values ('8b500000-0000-4000-8000-000000000001','8b200000-0000-4000-8000-000000000001','8b400000-0000-4000-8000-000000000001','api-module',1,'{"en":"Module","ar":"وحدة"}','{"en":"Description","ar":"وصف"}','{}');
insert into public.training_lessons(id,organization_id,course_version_id,module_id,stable_key,position,lesson_type,required,title_i18n,objective_i18n,content_i18n,pass_threshold_bps,max_attempts,retry_delay_seconds,metadata)
values ('8b600000-0000-4000-8000-000000000001','8b200000-0000-4000-8000-000000000001','8b400000-0000-4000-8000-000000000001','8b500000-0000-4000-8000-000000000001','api-quiz',1,'quiz',true,'{"en":"Quiz","ar":"اختبار"}','{"en":"Objective","ar":"هدف"}','{"en":"","ar":""}',8000,3,0,'{}');

select has_function('public','list_internal_admin_training_question_drafts',array['uuid','uuid','uuid','uuid','uuid'],'list RPC exists');
select has_function('public','create_internal_admin_training_question_draft',array['uuid','uuid','uuid','uuid','uuid','uuid','text','text','integer','jsonb','jsonb','text','jsonb'],'create RPC exists');
select has_function('public','update_internal_admin_training_question_draft',array['uuid','uuid','uuid','uuid','uuid','uuid','bigint','uuid','text','text','integer','jsonb','jsonb','text','jsonb'],'update RPC exists');
select has_function('public','delete_internal_admin_training_question_draft',array['uuid','uuid','uuid','uuid','uuid','uuid','bigint','uuid','text'],'delete RPC exists');
select has_function('public','replace_internal_admin_training_question_options',array['uuid','uuid','uuid','uuid','uuid','uuid','bigint','uuid','text','text','jsonb'],'replace-options RPC exists');
select is((select count(*)::integer from pg_proc where proname like '%internal_admin_training_question%' and prosecdef and proconfig @> array['search_path=""']),5,'all authoring RPCs are SECURITY DEFINER with empty search_path');
select ok(has_function_privilege('service_role','public.create_internal_admin_training_question_draft(uuid,uuid,uuid,uuid,uuid,uuid,text,text,integer,jsonb,jsonb,text,jsonb)','execute'),'service_role can execute authoring RPC');
select ok(not has_function_privilege('anon','public.create_internal_admin_training_question_draft(uuid,uuid,uuid,uuid,uuid,uuid,text,text,integer,jsonb,jsonb,text,jsonb)','execute') and not has_function_privilege('authenticated','public.create_internal_admin_training_question_draft(uuid,uuid,uuid,uuid,uuid,uuid,text,text,integer,jsonb,jsonb,text,jsonb)','execute'),'browser roles cannot execute authoring RPC');
select ok(not has_table_privilege('service_role','public.training_question_drafts','select') and not has_table_privilege('authenticated','public.training_question_draft_options','insert'),'direct draft table access remains denied');

create temporary table authoring_results(payload jsonb) on commit drop;
insert into authoring_results select public.create_internal_admin_training_question_draft(
 actor_user_id := '8b100000-0000-4000-8000-000000000001', target_organization_id := '8b200000-0000-4000-8000-000000000001', target_course_id := '8b300000-0000-4000-8000-000000000001', target_course_version_id := '8b400000-0000-4000-8000-000000000001', target_lesson_id := '8b600000-0000-4000-8000-000000000001', action_key := '8b700000-0000-4000-8000-000000000001', request_hash := repeat('1',64), stable_key := 'api-question-one', p_position := 1, prompt_i18n := '{"en":"Question one?","ar":"السؤال الأول؟"}', explanation_i18n := '{"en":"Explanation","ar":"شرح"}', correct_option_key := 'yes', options := '[{"option_key":"yes","position":1,"label_i18n":{"en":"Yes","ar":"نعم"}},{"option_key":"no","position":2,"label_i18n":{"en":"No","ar":"لا"}}]');
select ok((select payload->>'id' from authoring_results) is not null,'create returns canonical persisted state');
select is((select count(*)::integer from public.training_question_draft_options where question_id=(select (payload->>'id')::uuid from authoring_results)),2,'create atomically persists two options');
select is((select count(*)::integer from public.list_internal_admin_training_question_drafts('8b100000-0000-4000-8000-000000000001','8b200000-0000-4000-8000-000000000001','8b300000-0000-4000-8000-000000000001','8b400000-0000-4000-8000-000000000001','8b600000-0000-4000-8000-000000000001')),1,'list is scoped to the quiz lesson');

select lives_ok($$select public.update_internal_admin_training_question_draft(
 '8b100000-0000-4000-8000-000000000001','8b200000-0000-4000-8000-000000000001','8b300000-0000-4000-8000-000000000001','8b400000-0000-4000-8000-000000000001','8b600000-0000-4000-8000-000000000001',(select (payload->>'id')::uuid from authoring_results),0,'8b700000-0000-4000-8000-000000000002',repeat('2',64),'api-question-one',1,'{"en":"Updated?","ar":"محدث؟"}','{"en":"Updated","ar":"محدث"}','yes','[{"option_key":"yes","position":1,"label_i18n":{"en":"Yes","ar":"نعم"}},{"option_key":"no","position":2,"label_i18n":{"en":"No","ar":"لا"}}]')$$,'update succeeds at revision zero');
select is((select revision from public.training_question_drafts where id=(select (payload->>'id')::uuid from authoring_results)),1::bigint,'update increments revision');
select lives_ok($$select public.replace_internal_admin_training_question_options(
 '8b100000-0000-4000-8000-000000000001','8b200000-0000-4000-8000-000000000001','8b300000-0000-4000-8000-000000000001','8b400000-0000-4000-8000-000000000001','8b600000-0000-4000-8000-000000000001',(select (payload->>'id')::uuid from authoring_results),1,'8b700000-0000-4000-8000-000000000003',repeat('3',64),'first','[{"option_key":"first","position":1,"label_i18n":{"en":"First","ar":"أول"}},{"option_key":"second","position":2,"label_i18n":{"en":"Second","ar":"ثان"}}]')$$,'options are replaced atomically');
select is((select revision from public.training_question_drafts where id=(select (payload->>'id')::uuid from authoring_results)),2::bigint,'option replacement increments revision');
select is((select count(*)::integer from public.training_question_draft_options where question_id=(select (payload->>'id')::uuid from authoring_results) and option_key='second'),1,'replacement removes the old option set');
select throws_ok($$select public.update_internal_admin_training_question_draft('8b100000-0000-4000-8000-000000000001','8b200000-0000-4000-8000-000000000001','8b300000-0000-4000-8000-000000000001','8b400000-0000-4000-8000-000000000001','8b600000-0000-4000-8000-000000000001',(select (payload->>'id')::uuid from authoring_results),1,'8b700000-0000-4000-8000-000000000004',repeat('4',64),'api-question-one',2,'{"en":"Stale","ar":"قديم"}','{"en":"Stale","ar":"قديم"}','first','[{"option_key":"first","position":1,"label_i18n":{"en":"First","ar":"أول"}},{"option_key":"second","position":2,"label_i18n":{"en":"Second","ar":"ثان"}}]')$$,'40001','question revision is stale','stale revision is rejected');
select throws_ok($$select public.create_internal_admin_training_question_draft('8b100000-0000-4000-8000-000000000002','8b200000-0000-4000-8000-000000000001','8b300000-0000-4000-8000-000000000001','8b400000-0000-4000-8000-000000000001','8b600000-0000-4000-8000-000000000001','8b700000-0000-4000-8000-000000000005',repeat('5',64),'unauthorized',2,'{"en":"x","ar":"س"}','{"en":"x","ar":"س"}','yes','[{"option_key":"yes","position":1,"label_i18n":{"en":"Yes","ar":"نعم"}},{"option_key":"no","position":2,"label_i18n":{"en":"No","ar":"لا"}}]')$$,'42501','Training media access denied','non-admin cross-scope access is denied');

select is((public.create_internal_admin_training_question_draft('8b100000-0000-4000-8000-000000000001','8b200000-0000-4000-8000-000000000001','8b300000-0000-4000-8000-000000000001','8b400000-0000-4000-8000-000000000001','8b600000-0000-4000-8000-000000000001','8b700000-0000-4000-8000-000000000006',repeat('6',64),'api-question-two',2,'{"en":"Two?","ar":"الثاني؟"}','{"en":"Two","ar":"ثان"}','yes','[{"option_key":"yes","position":1,"label_i18n":{"en":"Yes","ar":"نعم"}},{"option_key":"no","position":2,"label_i18n":{"en":"No","ar":"لا"}}]')->>'stable_key'),'api-question-two','idempotency fixture creates once');
select is((public.create_internal_admin_training_question_draft('8b100000-0000-4000-8000-000000000001','8b200000-0000-4000-8000-000000000001','8b300000-0000-4000-8000-000000000001','8b400000-0000-4000-8000-000000000001','8b600000-0000-4000-8000-000000000001','8b700000-0000-4000-8000-000000000006',repeat('6',64),'api-question-two',2,'{"en":"Two?","ar":"الثاني؟"}','{"en":"Two","ar":"ثان"}','yes','[{"option_key":"yes","position":1,"label_i18n":{"en":"Yes","ar":"نعم"}},{"option_key":"no","position":2,"label_i18n":{"en":"No","ar":"لا"}}]')->>'stable_key'),'api-question-two','same idempotency key replays the canonical response');
select is((select count(*)::integer from public.training_question_drafts where stable_key='api-question-two'),1,'idempotent retry does not duplicate the question');
select throws_ok($$select public.create_internal_admin_training_question_draft('8b100000-0000-4000-8000-000000000001','8b200000-0000-4000-8000-000000000001','8b300000-0000-4000-8000-000000000001','8b400000-0000-4000-8000-000000000001','8b600000-0000-4000-8000-000000000001','8b700000-0000-4000-8000-000000000006',repeat('7',64),'different',2,'{"en":"Different?","ar":"مختلف؟"}','{"en":"Different","ar":"مختلف"}','yes','[{"option_key":"yes","position":1,"label_i18n":{"en":"Yes","ar":"نعم"}},{"option_key":"no","position":2,"label_i18n":{"en":"No","ar":"لا"}}]')$$,'23505','idempotency conflict','conflicting idempotency key is rejected');
select lives_ok($$select public.delete_internal_admin_training_question_draft('8b100000-0000-4000-8000-000000000001','8b200000-0000-4000-8000-000000000001','8b300000-0000-4000-8000-000000000001','8b400000-0000-4000-8000-000000000001','8b600000-0000-4000-8000-000000000001',(select id from public.training_question_drafts where stable_key='api-question-two'),0,'8b700000-0000-4000-8000-00000000000b',repeat('c',64))$$,'delete removes a draft question through the RPC');
select is((select count(*)::integer from public.training_question_drafts where stable_key='api-question-two'),0,'deleted question is no longer listed');
select throws_ok($$select public.create_internal_admin_training_question_draft('8b100000-0000-4000-8000-000000000001','8b200000-0000-4000-8000-000000000001','8b300000-0000-4000-8000-000000000001','8b400000-0000-4000-8000-000000000001','8b600000-0000-4000-8000-000000000001','8b700000-0000-4000-8000-000000000007',repeat('8',64),'duplicate-position',3,'{"en":"Duplicate?","ar":"مكرر؟"}','{"en":"Duplicate","ar":"مكرر"}','yes','[{"option_key":"yes","position":1,"label_i18n":{"en":"Yes","ar":"نعم"}},{"option_key":"no","position":1,"label_i18n":{"en":"No","ar":"لا"}}]')$$,'23505','question authoring conflict','duplicate option positions roll back');
select is((select count(*)::integer from public.training_question_drafts where stable_key='duplicate-position'),0,'failed option validation leaves no partial question');
select throws_ok($$select public.create_internal_admin_training_question_draft('8b100000-0000-4000-8000-000000000001','8b200000-0000-4000-8000-000000000001','8b300000-0000-4000-8000-000000000001','8b400000-0000-4000-8000-000000000001','8b600000-0000-4000-8000-000000000001','8b700000-0000-4000-8000-000000000008',repeat('9',64),'unsupported-locale',3,'{"en":"x","fr":"x"}','{"en":"x","fr":"x"}','yes','[{"option_key":"yes","position":1,"label_i18n":{"en":"Yes","ar":"نعم"}},{"option_key":"no","position":2,"label_i18n":{"en":"No","ar":"لا"}}]')$$,'22023','Training question locale content is invalid','unsupported locale is rejected');

update public.training_course_versions set status='retired',published_at=now(),published_by='8b100000-0000-4000-8000-000000000001',retired_at=now(),retired_by='8b100000-0000-4000-8000-000000000001',content_hash=repeat('b',64),publication_fingerprint=repeat('a',64) where id='8b400000-0000-4000-8000-000000000001';
select throws_ok($$select public.create_internal_admin_training_question_draft('8b100000-0000-4000-8000-000000000001','8b200000-0000-4000-8000-000000000001','8b300000-0000-4000-8000-000000000001','8b400000-0000-4000-8000-000000000001','8b600000-0000-4000-8000-000000000001','8b700000-0000-4000-8000-000000000009',repeat('a',64),'retired',3,'{"en":"x","ar":"س"}','{"en":"x","ar":"س"}','yes','[{"option_key":"yes","position":1,"label_i18n":{"en":"Yes","ar":"نعم"}},{"option_key":"no","position":2,"label_i18n":{"en":"No","ar":"لا"}}]')$$,'55000','Training course version is immutable','retired versions reject create');
select throws_ok($$select public.update_internal_admin_training_question_draft('8b100000-0000-4000-8000-000000000001','8b200000-0000-4000-8000-000000000001','8b300000-0000-4000-8000-000000000001','8b400000-0000-4000-8000-000000000001','8b600000-0000-4000-8000-000000000001',(select (payload->>'id')::uuid from authoring_results),2,'8b700000-0000-4000-8000-00000000000a',repeat('b',64),'api-question-one',1,'{"en":"x","ar":"س"}','{"en":"x","ar":"س"}','first','[{"option_key":"first","position":1,"label_i18n":{"en":"First","ar":"أول"}},{"option_key":"second","position":2,"label_i18n":{"en":"Second","ar":"ثان"}}]')$$,'55000','Training course version is immutable','retired questions reject update');
select is((select revision from public.training_question_drafts where id=(select (payload->>'id')::uuid from authoring_results)),2::bigint,'rejected retired update leaves question unchanged');

select * from finish();
rollback;
